const API = '/api';
const nav = [['⌂','Dashboard'],['✦','Create'],['◈','Production plan'],['▤','Storyboard'],['▥','Timeline'],['▱','Assets'],['▧','Templates'],['◫','Formats'],['⟳','Automations'],['◇','MCP tools'],['◷','Jobs'],['✓','Export'],['◎','Catalog'],['⚙','Settings']];
const store = { token:'', state:{projects:[],assets:[],jobs:[],capabilities:[],formatCatalogue:{formats:[],platforms:[],variantCount:0,presets:{}}}, releases:[], project:null, active:'Dashboard', selectedClip:null, dirty:false, saving:false, savePromise:null, renderedContent:'', poll:null };
const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = n => { if (!Number.isFinite(Number(n))) return '—'; const s = Math.max(0,Number(n)); return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(Math.floor(s%60)).padStart(2,'0')}`; };
const fmtBytes = n => { const x=Number(n)||0; return x<1e6?`${Math.round(x/1024)} KB`:`${(x/1e6).toFixed(1)} MB`; };
function toast(message, kind='ok'){ const el=$('#toast'); if(!el)return; el.textContent=message; el.dataset.kind=kind; el.classList.add('show'); clearTimeout(el._t); el._t=setTimeout(()=>el.classList.remove('show'),2800); }
function fail(message){ toast(message,'error'); const b=$('#errorBanner'); if(b){ b.textContent=message; b.hidden=false; } }
let sessionRecovery=null;
async function api(path, options={}) {
 const request=()=>fetch(`${API}${path}`,{...options,headers:{...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(store.token?{'X-Vyrelum-Token':store.token}:{}),...(options.headers||{})}});
 let res=await request();
 if(res.status===401&&path!=='/session'){
  // The server rejected this request before mutation. Renew its loopback
  // session once and retry without discarding unsaved editor state.
  sessionRecovery||=fetch(`${API}/session`).then(async r=>{if(!r.ok)throw Error('Local session unavailable');const session=await r.json();if(!session.token)throw Error('Local session unavailable');store.token=session.token;}).finally(()=>{sessionRecovery=null;});
  await sessionRecovery;res=await request();
  if(res.ok&&$('#errorBanner')?.textContent==='Session required'){$('#errorBanner').hidden=true;$('#errorBanner').textContent='';}
 }
 let data=null;try{data=await res.json();}catch{}if(!res.ok)throw new Error(data?.error||`${res.status} ${res.statusText}`);return data;
}
async function init(){ try { const session=await api('/session'); store.token=session.token||''; await refresh(); } catch(e){ fail(`Control plane unavailable: ${e.message}`); } render(); store.poll=setInterval(refresh,3500); }
async function refresh(){ try { const [state,releases]=await Promise.all([api('/state'),api('/releases')]); store.state={...state,projects:state.projects||[],assets:state.assets||[],jobs:state.jobs||[],capabilities:state.capabilities||[]}; store.releases=Array.isArray(releases)?releases:[]; const id=store.project?.id||localStorage.getItem('vyrelum:selectedProject'); if(id){ const p=store.state.projects.find(x=>x.id===id); const editableFocused=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName); if(p && !store.dirty && !store.saving && JSON.stringify(p)!==JSON.stringify(store.project)){ store.project=p; if(!p.timeline?.some(c=>c.id===store.selectedClip)) store.selectedClip=p.timeline?.[0]?.id||null; } if($('#app') && !(['Create','Timeline'].includes(store.active) && editableFocused)) updateDynamic(); } else if($('#app')) updateDynamic(); } catch(e){ if($('#app') && !$('#errorBanner')?.textContent) fail(e.message); } }
function projectCard(p){ const out=p.latestOutput?.videoAssetId?store.state.assets.find(a=>a.id===p.latestOutput.videoAssetId):null; const poster=p.latestOutput?.posterAssetId?store.state.assets.find(a=>a.id===p.latestOutput.posterAssetId):null; const provenance=p.latestOutput?.provenance||{}; const state=p.latestOutput?.status==='rejected'?'REJECTED':p.latestOutput?.status==='blocked'?'BLOCKED':provenance.generationStatus==='fallback'?'FALLBACK':provenance.generationStatus==='imported'?'IMPORTED':p.latestOutput?.status==='review_required'?'REVIEW':out?'RENDERED':'DRAFT'; return `<button class="project-card" data-open-project="${esc(p.id)}"><div class="project-art" ${poster&&state!=='BLOCKED'?`style="background-image:url('${esc(poster.url)}')"`:''}><span class="tag">${state}</span><span class="project-open">Open →</span></div><div class="project-info"><strong>${esc(p.name||'Untitled')}</strong><span>${fmt((p.timeline||[]).reduce((a,c)=>a+Number(c.duration||0),0))} · rev ${p.revision||0}${p.latestOutput?.status==='review_required'?' · visual review required':''}${p.latestOutput?.status==='blocked'?' · generation blocked':''}</span></div></button>`; }
function layout(content){ document.querySelector('#app').innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><div class="brand"><span class="brand-mark"></span>VYREALM</div><div class="eyebrow nav-section">Studio</div><nav>${nav.slice(0,6).map(navItem).join('')}</nav><div class="eyebrow nav-section">System</div><nav>${nav.slice(6).map(navItem).join('')}</nav><div class="sidebar-foot"><div class="profile"><div class="avatar">AL</div><div><strong>Local workspace</strong><div class="eyebrow">Offline control plane</div></div></div></div></aside><main class="main"><header class="topbar"><div class="top-left"><button class="icon-btn mobile-menu" id="menuBtn">☰</button><div class="crumb">Workspace <span>/</span> <strong>${esc(store.active)}</strong></div></div><div class="top-actions"><label class="search-wrap"><span>⌕</span><input class="search" id="search" placeholder="Search projects or assets" /></label><span class="credit">● LOCAL ONLY</span><button class="icon-btn" id="refreshBtn" aria-label="Refresh">↻</button></div></header><div id="errorBanner" class="error-banner" hidden></div><section class="content">${content}</section></main><input type="file" id="mediaInput" accept="image/*,video/*,audio/*" hidden><input type="file" id="bundleInput" accept="application/json,.json" hidden><div class="toast" id="toast"></div></div>`; bindLayout(); }
function navItem(item){ return `<button class="nav-item ${store.active===item[1]?'active':''}" data-nav="${item[1]}"><span class="nav-icon">${item[0]}</span>${item[1]}</button>`; }
function render(){ const content=store.active==='Dashboard'?explore():store.active==='Create'?studio():store.active==='Production plan'?cinema():store.active==='Storyboard'?storyboard():store.active==='Timeline'?studio():store.active==='Assets'?library():store.active==='Formats'?formatLab():store.active==='Jobs'?jobs():store.active==='MCP tools'?mcpTools():store.active==='Export'?review():store.active==='Catalog'?catalog():['Templates','Automations','Settings'].includes(store.active)?productSection(store.active):generic(store.active); store.renderedContent=content; layout(content); bindPage(); }
function bindLayout(){ document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{store.active=b.dataset.nav; render();}); $('#menuBtn')?.addEventListener('click',()=>$('#sidebar').classList.toggle('open')); $('#refreshBtn')?.addEventListener('click',async()=>{await refresh();render();toast('Workspace refreshed')}); $('#search')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase(); document.querySelectorAll('.project-card,.asset-row').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(q));}); }
function bindPage(){ document.querySelectorAll('[data-open-project]').forEach(b=>b.onclick=async()=>{ try{store.project=await api(`/projects/${b.dataset.openProject}`);store.dirty=false;store.selectedClip=store.project.timeline?.[0]?.id||null;localStorage.setItem('vyrelum:selectedProject',store.project.id);store.active='Create';render();}catch(e){fail(e.message);} }); $('#newProject')?.addEventListener('click',()=>{store.project=null;store.dirty=true;store.active='Create';render();}); $('#importBtn')?.addEventListener('click',()=>$('#bundleInput').click()); $('#uploadBtn')?.addEventListener('click',()=>$('#mediaInput').click()); $('#bundleInput')?.addEventListener('change',importBundle); $('#mediaInput')?.addEventListener('change',uploadAsset); $('#saveProject')?.addEventListener('click',saveProject); $('#saveProject2')?.addEventListener('click',saveProject); $('#renderBtn')?.addEventListener('click',()=>queueJob('render')); $('#sceneBtn')?.addEventListener('click',()=>queueJob('scene')); $('#directBtn')?.addEventListener('click',()=>queueJob('direct')); $('#produceBtn')?.addEventListener('click',()=>queueJob('produce')); $('#generateVariations')?.addEventListener('click',generateVariations); $('#exportBtn')?.addEventListener('click',exportProject); $('#prepareRelease')?.addEventListener('click',createRelease); $('#cancelBtn')?.addEventListener('click',()=>jobAction('cancel')); $('#retryBtn')?.addEventListener('click',()=>jobAction('retry')); document.querySelectorAll('[data-clip]').forEach(b=>b.onclick=()=>{store.selectedClip=b.dataset.clip;updateDynamic();}); document.querySelectorAll('[data-field]').forEach(el=>el.oninput=()=>{ if(!store.project)return; const clip=store.project.timeline?.find(c=>c.id===store.selectedClip); if(!clip)return; const key=el.dataset.field; clip[key]=key==='duration'||key==='trimStart'?Math.max(0,Number(el.value)||0):el.value; store.dirty=true; clearTimeout(store.saveTimer);store.saveTimer=setTimeout(()=>void saveProject(),1200); }); $('#soundtrackGain')?.addEventListener('input',e=>{if(!store.project?.soundtrack)return;store.project.soundtrack.gain=Math.max(0,Math.min(8,Number(e.target.value)||0));store.dirty=true;clearTimeout(store.saveTimer);store.saveTimer=setTimeout(()=>void saveProject(),1200);}); $('#soundtrackMuted')?.addEventListener('change',e=>{if(!store.project?.soundtrack)return;store.project.soundtrack.muted=Boolean(e.target.checked);store.dirty=true;clearTimeout(store.saveTimer);store.saveTimer=setTimeout(()=>void saveProject(),1200);}); $('#createProjectBtn')?.addEventListener('click',createProject); bindScene(); }
function bindScene(){const p=store.project;if(!p)return;$('#sceneObject')?.addEventListener('change',()=>{const o=p.scene?.objects?.find(x=>x.id===$('#sceneObject').value);if(o){const q=o.position||[0,0,0];document.querySelectorAll('[data-scene]').forEach((el,i)=>el.value=q[i]||0);}});document.querySelectorAll('[data-scene]').forEach(el=>el.oninput=()=>{const o=p.scene?.objects?.find(x=>x.id===$('#sceneObject')?.value)||p.scene?.objects?.[0];if(!o)return;o.position=o.position||[0,0,0];o.position[{x:0,y:1,z:2}[el.dataset.scene]]=Number(el.value)||0;store.dirty=true;clearTimeout(store.saveTimer);store.saveTimer=setTimeout(saveProject,1200);});$('[data-scene-light]')?.addEventListener('input',e=>{const l=p.scene?.lights?.[0];if(l){l.energy=Math.max(0,Number(e.target.value)||0);store.dirty=true;clearTimeout(store.saveTimer);store.saveTimer=setTimeout(saveProject,1200);}});}
function bindEvents(){ bindPage(); }
function updateDynamic(){ const content=$('.content'); if(!content)return; const editableFocused=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName); if(['Create','Production plan','Timeline','Storyboard','Export'].includes(store.active)&&editableFocused)return; const next=store.active==='Create'||store.active==='Timeline'?studio():store.active==='Jobs'?jobs():store.active==='Production plan'?cinema():store.active==='Storyboard'?storyboard():store.active==='Formats'?formatLab():store.active==='MCP tools'?mcpTools():store.active==='Catalog'?catalog():store.active==='Export'?review():['Templates','Automations','Settings'].includes(store.active)?productSection(store.active):null; if(next==null||next===store.renderedContent)return; const oldVideo=content.querySelector('video.media-preview'); const oldTime=oldVideo?.currentTime||0,wasPlaying=oldVideo&&!oldVideo.paused; content.innerHTML=next; store.renderedContent=next; bindPage(); const newVideo=content.querySelector('video.media-preview'); if(oldVideo&&newVideo&&oldVideo.getAttribute('src')===newVideo.getAttribute('src')){newVideo.replaceWith(oldVideo); try{oldVideo.currentTime=oldTime;if(wasPlaying)void oldVideo.play();}catch{}} }
async function createProject(){ const name=$('#projectName')?.value.trim()||'Untitled production', brief=$('#projectBrief')?.value.trim()||''; if(!brief){fail('Add a brief before creating the project.');return;} const profiles={1080:{width:1920,height:1080},2160:{width:3840,height:2160},720:{width:1280,height:720}}, mode=$('#projectMode')?.value||'cinematic', productTemplate=$('#productTemplate')?.value||'studio', productCamera=$('#productCamera')?.value||'dolly-in', sampleId=mode==='cinematic'?($('#cinematicSource')?.value||null):null; const resolution=$('#projectResolution')?.value||'1080', profile=mode==='product' ? profileForProduct(resolution) : (profiles[resolution]||profiles[1080]), fps=Math.max(12,Math.min(60,Number($('#projectFps')?.value)||24)); try{store.project=await api('/projects',{method:'POST',body:JSON.stringify({name,brief,mode,sampleId,productTemplate:mode==='product'?productTemplate:null,productCamera:mode==='product'?productCamera:null,durationSeconds:mode==='product'?15:sampleId==='rain-market'?15:null,settings:{...profile,fps}})});store.dirty=false;localStorage.setItem('vyrelum:selectedProject',store.project.id);toast(mode==='product'?'Product project created — import a product image':sampleId?'Cinematic test source attached':'Project created');render();}catch(e){fail(e.message);} }
async function generateVariations(){ if(!store.project)return; const button=$('#generateVariations'); if(button)button.disabled=true; try{const result=await api(`/projects/${store.project.id}/variations`,{method:'POST',body:JSON.stringify({expectedRevision:store.project.revision,count:120})});store.project=result;store.dirty=false;toast(`${Number(result.variationCount||0)} editable recipes saved`);render();}catch(e){fail(`Variation planning failed: ${e.message}`);}finally{if(button)button.disabled=false;} }
function studio(){const p=store.project; if(!p)return `<div class="hero"><div><div class="eyebrow">Create / New production</div><h1>Start with a <em>brief.</em></h1><p class="hero-copy">Describe the story, then choose a delivery profile. VYREALM keeps the production graph editable from the first frame to export.</p></div><div class="hero-note"><span class="hero-note-dot"></span>Local inference ready</div></div><div class="panel create-form"><div class="field"><label>PROJECT NAME</label><input id="projectName" placeholder="A name for this production"></div><div class="field"><label>BRIEF</label><textarea id="projectBrief" placeholder="Subject, setting, action, mood, and intended audience..."></textarea></div><div class="row profile-row"><div class="field"><label>PRODUCTION TYPE</label><select id="projectMode"><option value="cinematic">Cinematic film</option><option value="product">Product video / ad</option></select></div><div class="field"><label>PRODUCT TEMPLATE</label><select id="productTemplate"><option value="studio">Studio hero</option><option value="lifestyle">Lifestyle scene</option><option value="with-model">With model</option><option value="ugc-faceless">UGC faceless</option><option value="ugc-talking-head">UGC talking head</option><option value="ugc-silent">UGC silent</option><option value="motion-2d">2D product motion</option><option value="motion-mixed-media">Mixed media</option><option value="360-orbit">360 orbit</option><option value="unboxing">Unboxing</option><option value="demo">Product demo</option></select></div><div class="field"><label>CAMERA MOVE</label><select id="productCamera"><option value="dolly-in">Dolly in</option><option value="hero-orbit">Hero orbit</option><option value="pan-right">Pan right</option><option value="pan-left">Pan left</option><option value="crane-up">Crane up</option><option value="handheld">Handheld</option><option value="crash-zoom">Crash zoom</option><option value="static">Static hero</option></select></div></div><div class="profile-heading"><div><div class="eyebrow">Delivery profile</div><strong>Set the canvas before you direct</strong></div><span class="profile-badge">LOCAL EXPORT</span></div><div class="row profile-row"><div class="field"><label>RESOLUTION</label><select id="projectResolution"><option value="1080">Full HD · 1920 × 1080</option><option value="2160">Ultra HD · 3840 × 2160</option><option value="720">HD · 1280 × 720</option></select></div><div class="field"><label>FRAME RATE</label><select id="projectFps"><option value="24" selected>24 fps · Cinematic</option><option value="30">30 fps · Standard</option><option value="60">60 fps · Motion</option></select></div></div><div class="profile-foot"><span>Profile is stored with this project revision.</span><button class="btn primary" id="createProjectBtn">Create project <span>→</span></button></div></div>`; const clips=p.timeline||[], clip=clips.find(c=>c.id===store.selectedClip)||clips[0]; const asset=clip&&store.state.assets.find(a=>a.id===clip.assetId); const soundtrack=p.soundtrack; const settings=p.settings||{}; return `<div class="hero"><div><div class="eyebrow">Create / ${esc(p.name)}${p.mode==='product'?' · PRODUCT STUDIO':''}</div><h1>Shape a <em>world.</em></h1><p class="hero-copy">${esc(p.brief||'No brief recorded.')} <span class="revision">Revision ${p.revision}</span>${p.mode==='product'?'<span class="revision"> · '+esc(p.productTemplate||'studio')+' · '+esc(p.productCamera||'dolly-in')+(p.productAssetId?'':' · import a product image')+'</span>':''}</p></div><div class="hero-actions"><span class="output-chip">${Number(settings.width||640)} × ${Number(settings.height||360)} · ${Number(settings.fps||24)} FPS</span><button class="btn ghost" id="uploadBtn">＋ Import media</button><button class="btn" id="saveProject">Save revision</button><button class="btn" id="generateVariations">Plan 120 variants</button><button class="btn primary" id="produceBtn">Produce local film <span>→</span></button></div></div><div class="workspace"><div class="panel"><div class="panel-title"><h3>Timeline</h3><span class="eyebrow">${fmt(clips.reduce((n,c)=>n+Number(c.duration||0),0))} · ${clips.length} clips</span></div>${clips.length?`<div class="clip-list">${clips.map(c=>{const a=store.state.assets.find(x=>x.id===c.assetId);return `<button class="timeline-clip ${c.id===clip?.id?'selected':''}" data-clip="${esc(c.id)}"><span>${esc(a?.name||c.kind||'Clip')}</span><span>${fmt(c.duration)}</span></button>`}).join('')}</div><div class="timeline-editor"><div class="field"><label>DURATION (SECONDS)</label><input type="number" min="0.1" step="0.1" data-field="duration" value="${esc(clip?.duration||0)}"></div><div class="field"><label>TRIM START (SECONDS)</label><input type="number" min="0" step="0.1" data-field="trimStart" value="${esc(clip?.trimStart||0)}"></div><div class="field"><label>CAPTION</label><textarea data-field="caption" rows="3" placeholder="Caption for this shot">${esc(clip?.caption||'')}</textarea></div></div>`:`<div class="empty">Import a video or image to add the first clip.</div>`}${soundtrack?`<div class="timeline-editor soundtrack-editor"><div class="field"><label>SOUNDTRACK GAIN</label><input id="soundtrackGain" type="number" min="0" max="8" step="0.05" value="${esc(soundtrack.gain??1)}"></div><label class="checkbox"><input id="soundtrackMuted" type="checkbox" ${soundtrack.muted?'checked':''}> Mute soundtrack</label></div>`:''}<div class="panel-actions"><button class="btn" id="sceneBtn">Build 3D scene</button><button class="btn" id="directBtn">Plan only</button><button class="btn" id="renderBtn">Render edit</button><button class="btn" id="exportBtn">Export portable</button></div></div><div class="panel preview-panel"><div class="panel-title"><h3>Preview</h3><span class="tag" style="position:static">${p.latestOutput?'RENDERED':'EDITABLE'}</span></div>${preview(p,asset)}<div class="asset-strip">${store.state.assets.filter(a=>a.projectId===p.id||!a.projectId).slice(0,8).map(a=>`<button class="asset-chip" data-asset="${a.id}">${esc(a.name)}</button>`).join('')}</div></div></div>`; }
function profileForProduct(resolution){return resolution==='2160'?{width:2160,height:3840}:resolution==='720'?{width:720,height:1280}:{width:1080,height:1920};}
async function saveProject(){ if(!store.project)return false; if(store.savePromise)return store.savePromise; const p=JSON.parse(JSON.stringify(store.project)); store.saving=true; store.savePromise=(async()=>{let ok=false;try{const saved=await api(`/projects/${p.id}`,{method:'PATCH',body:JSON.stringify({expectedRevision:p.revision,name:p.name,brief:p.brief,mode:p.mode,sampleId:p.sampleId,productTemplate:p.productTemplate,productCamera:p.productCamera,productAssetId:p.productAssetId,durationSeconds:p.durationSeconds,timeline:p.timeline,scene:p.scene,settings:p.settings,soundtrack:p.soundtrack,audioTracks:p.audioTracks,narrationText:p.narrationText,transcript:p.transcript,captionsEnabled:p.captionsEnabled})}); const changed=store.project?.id===p.id&&JSON.stringify(store.project)!==JSON.stringify(p); if(changed){store.project={...store.project,revision:saved.revision,updatedAt:saved.updatedAt};store.dirty=true;}else{store.project=saved;store.dirty=false;} ok=true;toast('Saved revision '+saved.revision);updateDynamic();}catch(e){fail(`Save failed: ${e.message}`);}finally{store.saving=false;store.savePromise=null;} if(ok&&store.dirty){clearTimeout(store.saveTimer);store.saveTimer=setTimeout(()=>void saveProject(),250);} return ok;})(); return store.savePromise; }
async function uploadAsset(e){ const file=e.target.files?.[0]; if(!file)return; try{const h={'X-Filename':encodeURIComponent(file.name),'Content-Type':file.type||'application/octet-stream'};if(store.project)h['X-Project-Id']=store.project.id;const asset=await api('/assets',{method:'POST',headers:h,body:file});toast(`Imported ${file.name}`);await refresh(); if(store.project?.mode==='product' && asset.kind==='image'){store.project.productAssetId=asset.id;store.dirty=true;} if(store.project && ['video','image','audio'].includes(asset.kind)){ if(asset.kind==='audio')store.project.soundtrack={assetId:asset.id,gain:1}; else {store.project.timeline=store.project.timeline||[];store.project.timeline.push({id:crypto.randomUUID(),assetId:asset.id,kind:asset.kind,duration:Number(asset.metadata?.duration||5),trimStart:0,caption:'',color:'#8B5CF6'});}store.dirty=true;updateDynamic();} }catch(e){fail(`Import failed: ${e.message}`);}finally{e.target.value='';} }
async function importBundle(e){const file=e.target.files?.[0];if(!file)return;try{const text=await file.text();store.project=await api('/projects/import',{method:'POST',body:text});store.active='Create';store.dirty=false;localStorage.setItem('vyrelum:selectedProject',store.project.id);toast('Portable project imported');render();}catch(err){fail(`Import failed: ${err.message}`);}finally{e.target.value='';}}
async function jobAction(action){const id=$('#jobId')?.value;if(!id)return;try{const job=await api(`/jobs/${id}/${action}`,{method:'POST',body:'{}'});toast(`${action==='cancel'?'Cancellation':'Retry'} requested`);await refresh();render();}catch(e){fail(e.message);} }
async function exportProject(){if(!store.project)return;try{const blob=await api(`/projects/${store.project.id}/export`);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(blob,null,2)],{type:'application/json'}));a.download=`${(store.project.name||'vyrelum-project').replace(/[^a-z0-9]+/gi,'-').toLowerCase()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);toast('Portable project exported');}catch(e){fail(e.message);} }
async function createRelease(){if(!store.project)return;const channelId=$('#releaseChannel')?.value.trim(),title=$('#releaseTitle')?.value.trim()||store.project.name;if(!channelId||!title){fail('Channel ID and title are required before preparing a release.');return;}try{await api('/releases',{method:'POST',body:JSON.stringify({projectId:store.project.id,channelId,title,privacyStatus:$('#releasePrivacy')?.value||'private',containsSyntheticMedia:$('#releaseAi')?.checked!==false,aiRationale:'Generated or assisted media is disclosed for owner review.'})});await refresh();toast('Release package prepared locally');updateDynamic();}catch(e){fail(`Release package failed: ${e.message}`);} }
function explore(){const ps=store.state.projects;const active=store.state.jobs.filter(j=>['queued','running','cancelling','staging','validating'].includes(j.status)).length;return `<div class="hero explore-hero"><div><div class="eyebrow">Local director workspace <span class="live-dot">●</span></div><h1>From first idea to <em>final cut.</em></h1><p class="hero-copy">Build cinematic stories on your machine. Your briefs, source media, scene graphs, and revisions remain editable and private.</p></div><div class="hero-actions"><button class="btn ghost" id="importBtn">＋ Import project</button><button class="btn primary" id="newProject">✦ Start a film</button></div></div><div class="metrics"><div class="metric"><div class="metric-label">Projects</div><div class="metric-value">${ps.length}</div><div class="metric-trend">persisted locally</div></div><div class="metric"><div class="metric-label">Assets</div><div class="metric-value">${store.state.assets.length}</div><div class="metric-trend">indexed sources</div></div><div class="metric"><div class="metric-label">Active jobs</div><div class="metric-value">${active}</div><div class="metric-trend">durable queue</div></div><div class="metric"><div class="metric-label">Capabilities</div><div class="metric-value">${store.state.capabilities.filter(c=>c.available).length}/${store.state.capabilities.length||0}</div><div class="metric-trend">dependency checks on this host</div></div></div><div class="launchpad"><div><div class="eyebrow">Creative launchpad</div><h2>Choose your next move</h2><p>Jump into the part of the workflow you need. Every route writes to the same project store.</p></div><div class="launch-actions"><button class="launch-action" data-nav="Create"><span class="launch-icon">✦</span><span><strong>Start from a brief</strong><small>Generate a structured production</small></span><b>→</b></button><button class="launch-action" data-nav="Production plan"><span class="launch-icon">◈</span><span><strong>Direct a sequence</strong><small>Shape shots and pacing</small></span><b>→</b></button><button class="launch-action" data-nav="Assets"><span class="launch-icon">▱</span><span><strong>Bring your footage</strong><small>Import video, images, or audio</small></span><b>→</b></button></div></div><div class="section-head"><h2>Your productions</h2><span class="meta">${ps.length?'Open a saved revision':'Create your first project'}</span></div>${ps.length?`<div class="grid project-grid">${ps.map(projectCard).join('')}</div>`:`<div class="empty"><strong>No projects yet</strong>Create a brief to start a real, editable production.</div>`}`;}
function preview(p,asset){if(p.latestOutput?.status==='blocked')return '<div class="preview-empty"><strong>Output blocked</strong><small>Review the job diagnostic before rendering again.</small></div>';const out=p.latestOutput?.videoAssetId&&store.state.assets.find(a=>a.id===p.latestOutput.videoAssetId);const src=out?.url||asset?.url; if(src && (out?.mime||asset?.mime||'').startsWith('video'))return `<video class="media-preview" controls preload="metadata" src="${esc(src)}"></video><a class="btn" data-job-id="${esc(p.latestOutput?.jobId||'')}" href="${esc(src)}" download="${esc((p.name||'vyrealm').replace(/[^a-z0-9-]+/gi,'-'))}.mp4">Download video</a>`; if(src && (out?.mime||asset?.mime||'').startsWith('image'))return `<img class="media-preview" src="${esc(src)}" alt="${esc(asset?.name||p.name)}">`; return `<div class="preview-empty"><span>◈</span><strong>${p.latestOutput?.status==='review_required'?'Visual review required':p.latestOutput?'No accepted preview':'Preview appears here'}</strong><small>${p.latestOutput?.status==='review_required'?'Technical checks passed; semantic visual review is still required.':p.latestOutput?'Open the rendered asset from this project.':'Import media or render a project to see playable output.'}</small></div>`; }
function cinema(){const p=store.project,clips=p?.timeline||[],settings=p?.settings||{};return `<div class="hero cinema-hero"><div><div class="eyebrow">Cinema / Director suite</div><h1>Direct the <em>sequence.</em></h1><p class="hero-copy">Turn a brief into a sequence of deliberate shots. Review pacing, coverage, and the editable scene before you render.</p></div>${p?`<div class="hero-actions"><span class="output-chip">${Number(settings.width||640)} × ${Number(settings.height||360)} · ${Number(settings.fps||24)} FPS</span><button class="btn" id="saveProject2">Save changes</button><button class="btn primary" id="directBtn">Run director <span>→</span></button></div>`:''}</div>${p?`<div class="director-overview"><div class="director-title"><div><div class="eyebrow">Current production</div><h2>${esc(p.name)}</h2></div><span class="revision-pill">REV ${p.revision||0}</span></div><p>${esc(p.brief||'No brief recorded.')}</p><div class="director-stats"><div><span>SHOTS</span><strong>${clips.length}</strong></div><div><span>RUNTIME</span><strong>${fmt(clips.reduce((n,c)=>n+Number(c.duration||0),0))}</strong></div><div><span>DELIVERY</span><strong>${Number(settings.fps||24)} FPS</strong></div><div><span>STATE</span><strong>${p.latestOutput?'Rendered':'In progress'}</strong></div></div></div><div class="storyboard-grid">${clips.length?clips.map((c,i)=>{const a=store.state.assets.find(x=>x.id===c.assetId);return `<button class="storyboard-card ${c.id===store.selectedClip?'selected':''}" data-clip="${esc(c.id)}"><div class="storyboard-number">${String(i+1).padStart(2,'0')}</div><div class="storyboard-art" ${a?.url&&a.kind==='image'?`style="background-image:url('${esc(a.url)}')"`:''}><span>${esc((a?.kind||'SHOT').toUpperCase())}</span></div><div class="storyboard-copy"><strong>${esc(a?.name||c.kind||'Untitled shot')}</strong><span>${fmt(c.duration)} · ${esc(c.caption||'No caption')}</span></div></button>`}).join(''):`<div class="empty"><strong>No shots yet</strong>Run the director or import footage from Create.</div>`}</div>`:`<div class="empty"><strong>Open a project first</strong>Choose a production from Explore.</div>`}`;}
function canvas(){const p=store.project,s=p?.scene||{objects:[],lights:[],camera:{}},o=s.objects?.[0],l=s.lights?.[0],pos=o?.position||[0,0,0];return `<div class="hero"><div><div class="eyebrow">Canvas / Production graph</div><h1>See every <em>layer.</em></h1><p class="hero-copy">Canvas reads the same scene document as Cinema. Transform edits stay attached to the project revision.</p></div>${p?`<div class="hero-actions"><button class="btn" id="saveProject2">Save revision</button><button class="btn primary" id="sceneBtn">Build / render scene</button></div>`:''}</div>${p?`<div class="workspace"><div class="panel"><div class="panel-title"><h3>Scene objects</h3><span class="eyebrow">${s.objects?.length||0} objects</span></div>${s.objects?.length?`<select id="sceneObject" class="scene-select">${s.objects.map(x=>`<option value="${esc(x.id)}">${esc(x.id)} · ${esc(x.type||'object')}</option>`).join('')}</select><div class="row"><div class="field"><label>POSITION X (M)</label><input type="number" step="0.01" data-scene="x" value="${Number(pos[0]||0)}"></div><div class="field"><label>POSITION Y (M)</label><input type="number" step="0.01" data-scene="y" value="${Number(pos[1]||0)}"></div></div><div class="field"><label>POSITION Z (M)</label><input type="number" step="0.01" data-scene="z" value="${Number(pos[2]||0)}"></div>`:`<div class="empty">No scene objects yet. Run Build / render scene.</div>`}<h3 class="subhead">Light</h3>${l?`<div class="field"><label>ENERGY</label><input type="number" min="0" step="1" data-scene-light value="${Number(l.energy||0)}"></div>`:`<div class="empty">No lights in this scene.</div>`}</div><div class="panel scene-summary"><div class="panel-title"><h3>Canonical scene</h3><span class="tag" style="position:static">EDITABLE</span></div><pre>${esc(JSON.stringify(s,null,2))}</pre></div></div>`:`<div class="empty"><strong>Open a project first</strong>Open a project to inspect its scene graph.</div>`}`;}
function library(){const assets=store.state.assets;return `<div class="hero"><div><div class="eyebrow">Library / Sources</div><h1>Your creative <em>memory.</em></h1><p class="hero-copy">Immutable source files and generated artifacts reported by the local control plane.</p></div><button class="btn primary" id="uploadBtn">＋ Import media</button></div><div class="panel asset-table">${assets.length?assets.map(a=>`<div class="asset-row"><span class="asset-kind">${esc(a.kind||'file')}</span><strong>${esc(a.name)}</strong><span>${esc(a.mime||'')} · ${fmtBytes(a.size)}</span><a href="${esc(a.url)}" target="_blank" rel="noreferrer">Open</a></div>`).join(''):`<div class="empty">No assets indexed yet.</div>`}</div>`;}
function jobs(){const jobs=store.state.jobs;return `<div class="hero"><div><div class="eyebrow">Jobs / Durable queue</div><h1>Nothing gets <em>lost.</em></h1><p class="hero-copy">Jobs survive a refresh and expose their actual stage, revision, and error. Retained shots can be inspected and applied after a project revision changes.</p></div></div><div class="panel job-table">${jobs.length?jobs.map(j=>`<div class="job-row"><div><strong>${esc(j.type)}</strong><span>${esc(j.projectId||'workspace')} · rev ${esc(j.revision||'—')}</span></div><span class="status ${esc(j.status)}">${esc(j.status)}${j.progress!=null?' · '+Math.round(j.progress*100)+'%':''}</span><span class="job-stage">${esc(j.stage||j.error||'')}</span>${['queued','loading','running','validating','awaiting_review'].includes(j.status)?`<button class="btn small" data-job-cancel="${j.id}">Cancel</button>`:''}${['failed','cancelled'].includes(j.status)||j.status==='blocked'&&['generation-test','generation-shot'].includes(j.type)?`<button class="btn small" data-job-retry="${j.id}">Retry</button>`:''}${retainedShotAction(j)}</div>`).join(''):`<div class="empty">No jobs have been queued.</div>`}</div>`;}
function retainedShotAction(job){
 if(!['generation-test','generation-shot'].includes(job.type)||job.output?.promoted!==false||!job.output?.assets?.video||!['review_required','rejected','succeeded'].includes(job.status))return '';
 const project=store.state.projects.find(p=>p.id===job.projectId),applied=project?.operations?.some(op=>op.type==='apply_generated_shot'&&op.jobId===job.id);
 if(applied)return '<span class="meta">Retained shot applied</span>';
 return `<button class="btn small" data-retained-shot="${esc(job.id)}">${job.status==='succeeded'&&job.output.review?.verdict==='passed'?'Apply reviewed shot':'Review retained shot'}</button>`;
}
async function openRetainedShot(jobId){
 $('#retainedShotDialog')?.close();
 const dialog=document.createElement('dialog');dialog.id='retainedShotDialog';dialog.className='panel';dialog.setAttribute('aria-labelledby','retainedShotTitle');dialog.style.cssText='width:min(920px,calc(100vw - 32px));max-height:90vh;overflow:auto;color:var(--text);margin:auto;box-shadow:0 24px 100px #000b;';
 dialog.innerHTML='<div class="panel-title"><h3 id="retainedShotTitle">Retained generated shot</h3><button class="btn small" id="closeRetainedShot">Close</button></div><p role="status">Loading the saved job and its project…</p>';
 document.body.appendChild(dialog);dialog.addEventListener('close',()=>{dialog.querySelector('video')?.pause();dialog.remove();});dialog.querySelector('#closeRetainedShot').onclick=()=>dialog.close();dialog.showModal();
 try{const jobs=await api('/jobs'),job=jobs.find(j=>j.id===jobId);if(!job?.projectId)throw Error('The retained generated job is unavailable.');const project=await api(`/projects/${encodeURIComponent(job.projectId)}`);if(dialog.isConnected)renderRetainedShot(dialog,job,project);}
 catch(error){if(dialog.isConnected){const message=dialog.querySelector('[role="status"]');if(message){message.setAttribute('role','alert');message.textContent=error.message;}}}
}
function renderRetainedShot(dialog,job,project,{applied=false}={}){
 const output=job.output||{},assets=output.assets||{},passed=job.status==='succeeded'&&output.review?.verdict==='passed',provenance=output.provenance||{};
 const media=id=>`/media/${encodeURIComponent(id)}`;
 applied=applied||Boolean(project.operations?.some(op=>op.type==='apply_generated_shot'&&op.jobId===job.id));
 dialog.innerHTML=`<div class="panel-title"><div><h3 id="retainedShotTitle">Retained shot · ${esc(project.name||'Untitled project')}</h3><p class="meta">Job ${esc(job.id.slice(0,8))} · generated at revision ${esc(job.revision)} · current project revision ${esc(project.revision)}</p></div><button class="btn small" id="closeRetainedShot">Close</button></div><p>This completed shot was retained when the project changed. Inspect its movement, faces, hands and continuity before recording your decision.</p>${assets.video?`<video id="retainedShotVideo" class="media-preview" aria-label="Retained generated shot video" controls preload="metadata" src="${esc(media(assets.video))}" style="width:100%;max-height:45vh"></video><a class="btn small" href="${esc(media(assets.video))}" download>Download retained video</a>`:'<p role="alert">The saved job has no playable output asset.</p>'}${assets.poster?`<details><summary>Inspect contact sheet</summary><img alt="Retained shot contact sheet" src="${esc(media(assets.poster))}" style="max-width:100%;height:auto"></details>`:''}<p class="meta">${esc(provenance.providerId||'Provider unrecorded')} · ${esc(provenance.modelId||'Model unrecorded')} · ${esc(provenance.generationStatus||'Unrecorded source method')}</p><div class="field"><label for="retainedReviewNotes">REVIEW NOTES</label><textarea id="retainedReviewNotes" maxlength="4000" placeholder="Describe what you inspected and any visible defects.">${esc(output.review?.notes||'')}</textarea></div><div class="panel-actions"><button class="btn" data-retained-verdict="passed" ${!assets.video?'disabled':''}>Record passed review</button><button class="btn" data-retained-verdict="rejected" ${!assets.video?'disabled':''}>Reject retained shot</button></div><p id="retainedShotStatus" role="status" class="meta">${applied?'Applied to the saved project. Existing edits were retained.':passed?'Passed review recorded. This shot can now be applied to its project.':'Review is required. A playable file alone does not establish visual quality.'}</p><p class="meta">Apply attaches the reviewed assets and appends this five-second shot once. Existing timeline edits remain intact. It does not regenerate footage or replace the project.</p><button class="btn primary" id="applyRetainedShot" ${!passed||applied?'disabled':''}>${applied?'Applied to project':'Apply reviewed shot'}</button><p class="meta" style="overflow-wrap:anywhere">Output hash: ${esc(provenance.outputHash||'Unrecorded')}</p>`;
 dialog.querySelector('#closeRetainedShot').onclick=()=>dialog.close();
 const status=dialog.querySelector('#retainedShotStatus');
 dialog.querySelectorAll('[data-retained-verdict]').forEach(button=>button.onclick=async()=>{
   const notes=dialog.querySelector('#retainedReviewNotes').value.trim();if(!notes){status.textContent='Add notes from inspecting the actual clip before recording a review.';dialog.querySelector('#retainedReviewNotes').focus();return;}
   dialog.querySelectorAll('[data-retained-verdict],#applyRetainedShot').forEach(el=>el.disabled=true);
   try{await api('/generation/review',{method:'POST',body:JSON.stringify({jobId:job.id,verdict:button.dataset.retainedVerdict,notes})});const jobs=await api('/jobs'),freshJob=jobs.find(j=>j.id===job.id),freshProject=await api(`/projects/${encodeURIComponent(job.projectId)}`);if(!freshJob)throw Error('The reviewed job is unavailable.');if(dialog.isConnected)renderRetainedShot(dialog,freshJob,freshProject);await refresh();toast('Retained shot review recorded');}
   catch(error){status.textContent=error.message;dialog.querySelectorAll('[data-retained-verdict]').forEach(el=>el.disabled=false);if(passed&&!applied)dialog.querySelector('#applyRetainedShot').disabled=false;}
 });
 dialog.querySelector('#applyRetainedShot').onclick=async e=>{
   const button=e.currentTarget;button.disabled=true;
   try{if(store.project?.id===job.projectId&&store.dirty&&!await saveProject())throw Error('Save the current project edits before applying this shot.');if(store.project?.id===job.projectId&&store.savePromise)await store.savePromise;const freshProject=await api(`/projects/${encodeURIComponent(job.projectId)}`);const result=await api('/generation/apply-retained',{method:'POST',body:JSON.stringify({projectId:job.projectId,jobId:job.id,expectedRevision:freshProject.revision})});if(store.project?.id===job.projectId&&!store.dirty)store.project=result.project;if(dialog.isConnected)renderRetainedShot(dialog,job,result.project,{applied:true});await refresh();toast(result.alreadyApplied?'Shot was already applied; no duplicate added':'Reviewed shot applied; existing edits retained');}
   catch(error){status.textContent=error.message;if(button.isConnected)button.disabled=false;}
 };
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-retained-shot]');if(button)void openRetainedShot(button.dataset.retainedShot);});
function models(){const h=store.state.hardware,p=h?.profile;return `<div class="hero"><div><div class="eyebrow">Models / Capability map</div><h1>Know your <em>engines.</em></h1><p class="hero-copy">Availability and evidence come from this machine, not decorative badges.</p></div></div>${p?`<div class="panel hardware-card"><div class="eyebrow">Measured hardware profile</div><h2>${esc(p.label)} <span class="meta">${esc(p.id)}</span></h2><p>${esc(p.reason)}</p><div class="meta">${esc(p.gpu||'No discrete GPU')} · ${Number(p.vramGb||0).toFixed(1)} GB VRAM · ${Number(p.ramGb||0).toFixed(1)} GiB RAM</div></div>`:''}<div class="cap-grid">${store.state.capabilities.length?store.state.capabilities.map(c=>`<div class="panel capability"><span class="status ${c.available?'succeeded':'failed'}">${c.available?'AVAILABLE':'UNAVAILABLE'}</span><h3>${esc(c.label||c.id)}</h3><p>${esc(c.reason||c.status||'No details reported')}</p></div>`).join(''):`<div class="empty">Capabilities have not been reported by the control plane.</div>`}</div>`;}
function review(){const p=store.project;return `<div class="hero"><div><div class="eyebrow">Review / Evidence</div><h1>Make it <em>reviewable.</em></h1><p class="hero-copy">Inspect the actual output attached to a project revision, then prepare a guarded local release package.</p></div></div>${p?`<div class="panel review-preview">${preview(p,null)}<div class="review-meta"><strong>${esc(p.name)}</strong><span>Revision ${p.revision} · updated ${esc(p.updatedAt||'')}</span></div><div class="release-form"><div class="field"><label>YOUTUBE CHANNEL ID</label><input id="releaseChannel" placeholder="UC…"></div><div class="field"><label>RELEASE TITLE</label><input id="releaseTitle" value="${esc(p.title||p.name||'Untitled')}" /></div><div class="row"><div class="field"><label>PRIVACY</label><select id="releasePrivacy"><option value="private">Private (review first)</option><option value="unlisted">Unlisted</option><option value="public">Public (permissioned adapter required)</option></select></div><label class="check"><input id="releaseAi" type="checkbox" checked> Disclose synthetic media</label></div><button class="btn primary" id="prepareRelease">Prepare local release package</button></div></div>`:`<div class="empty"><strong>No project selected</strong>Open a project to review its output.</div>`}${store.releases.length?`<div class="panel"><div class="panel-title"><h3>Release packages</h3><span class="eyebrow">local state</span></div>${store.releases.map(r=>`<div class="job-row"><div><strong>${esc(r.metadata?.title||r.id)}</strong><span>${esc(r.metadata?.channelId||'')} · rev ${esc(r.project?.revision||'')}</span></div><span class="status ${esc(r.state)}">${esc(r.state)}</span><span class="job-stage">${esc(r.output?.sha256?.slice(0,12)||'')}</span></div>`).join('')}</div>`:''}`;}
function formatLab(){const fc=store.state.formatCatalogue||{},formats=fc.formats||[],platforms=fc.platforms||[],p=fc.presets||{};return `<div class="hero"><div><div class="eyebrow">Formats / Executable recipes</div><h1>Direct for every <em>canvas.</em></h1><p class="hero-copy">Validated beat maps for reels, shorts, long-form, anime, podcasts, explainers, products, and narrative film. They plan real source requirements and remain unrendered until every shot is resolved.</p></div><div class="hero-actions"><span class="output-chip">${Number(fc.variantCount||0)} FORMAT × PLATFORM ROUTES</span><button class="btn primary" data-nav="Create">Use a project →</button></div></div><div class="metrics"><div class="metric"><div class="metric-label">Formats</div><div class="metric-value">${formats.length}</div><div class="metric-trend">structurally validated</div></div><div class="metric"><div class="metric-label">Camera controls</div><div class="metric-value">${Number(p.cameras||0)}</div><div class="metric-trend">bounded presets</div></div><div class="metric"><div class="metric-label">Looks</div><div class="metric-value">${Number(p.looks||0)}</div><div class="metric-trend">local grade intents</div></div><div class="metric"><div class="metric-label">Transitions</div><div class="metric-value">${Number(p.transitions||0)}</div><div class="metric-trend">FFmpeg qualified</div></div></div><div class="panel"><div class="panel-title"><h3>Delivery canvases</h3><span class="eyebrow">safe-area evidence retained</span></div><div class="platform-list">${platforms.map(x=>`<span class="output-chip">${esc(x.label)} · ${Number(x.canvas?.width||0)}×${Number(x.canvas?.height||0)} · ${Number(x.canvas?.fps||0)} FPS</span>`).join('')}</div></div><div class="section-head"><h2>Production recipes</h2><span class="meta">Plans are recipes, not rendered films</span></div><div class="feature-grid">${formats.map((x,i)=>`<div class="panel feature-card"><span class="feature-index">${String(i+1).padStart(2,'0')}</span><h3>${esc(x.label)}</h3><p>${esc(x.niche)} · ${Number(x.seconds||0)}s · ${Number(x.beatCount||0)} beats</p><div class="meta">${(x.platforms||[]).map(esc).join(' · ')}</div><div class="meta">${esc(x.hook)} · ${esc(x.captions)} · ${esc(x.audio)}</div></div>`).join('')}</div>`;}
function productSection(name){
  if(name==='Settings')return `<div class="hero"><div><div class="eyebrow">Settings / This computer</div><h1>Your local <em>engine.</em></h1><p class="hero-copy">Models are installed once. Generation uses this computer, without API keys or usage credits.</p></div></div><div class="panel"><div class="panel-title"><h3>Video runtime</h3><button class="btn" id="startLocalRuntime">Start / check local engine</button></div><p id="localRuntimeStatus">Reading installed runtime and hardware…</p><div class="provenance-grid" id="localRuntimeDetails"></div><p class="meta">First setup downloads about 8.3 GB of model files plus the Python/CUDA runtime. Windows setup includes a private Python runtime and pinned video, narration and transcription models. Allow 25 GB free for setup; models and retained film intermediates need additional working space. Setup uses the internet once. New-install qualification is still in progress.</p></div>${models()}`;
  const recipes=name==='Templates'?[['Local cinematic shot','Generate a new keyframe and five seconds of motion with the installed Wan model.','Create'],['Product edit','Import a real product image or clip, then choose camera motion and a delivery canvas.','Create'],['Footage and captions','Import footage, arrange clips, edit captions and render the timeline.','Timeline'],['Review and delivery','Inspect a saved render, download it and prepare a local release package.','Export']]:[['Generate a local shot','Queue the selected project through the local model. Inspect its durable job and visual output.','Create'],['Render an edit','Use the same timeline renderer from the studio or the local MCP bridge.','Timeline'],['Review job evidence','Inspect progress, provider errors and verification before accepting a render.','Jobs'],['Automation tools','Typed MCP actions expose supported operations and explicit unavailable capabilities.','MCP tools']];
  return `<div class="hero"><div><div class="eyebrow">VYREALM / ${esc(name)}</div><h1>${esc(name)} for <em>makers.</em></h1><p class="hero-copy">Open a working studio action. Source media and model requirements are shown before production.</p></div></div><div class="feature-grid">${recipes.map(([title,description,target],i)=>`<button class="panel feature-card" data-nav="${esc(target)}"><span class="feature-index">0${i+1}</span><h3>${esc(title)}</h3><p>${esc(description)}</p><span>Open ${esc(target)} →</span></button>`).join('')}</div>`;
}
