function enforceOutputTrust(){
  const p=store.project, panel=$('.preview-panel');
  if(!p||!panel)return;
  const badge=panel.querySelector('.panel-title .tag');
  const provenance=p.latestOutput?.provenance||{};
  if(badge)badge.textContent=p.latestOutput?.status==='rejected'?'REJECTED':p.latestOutput?.status==='blocked'?'BLOCKED':provenance.generationStatus==='fallback'?'FALLBACK':provenance.generationStatus==='imported'?'IMPORTED':p.latestOutput?.status==='review_required'?'REVIEW':p.latestOutput?'RENDERED':'EDITABLE';
  if(p.latestOutput?.status==='blocked'){
    const media=panel.querySelector('.media-preview');
    if(media)media.outerHTML=`<div class="preview-empty"><span>!</span><strong>${provenance.generationStatus==='blocked'?'Neural generation blocked':'Legacy output blocked'}</strong><small>${provenance.generationStatus==='blocked'?'No qualified local provider and verified adapter produced this shot. Import local media or run the labelled fallback.':'This project points to a primitive placeholder render. Queue a labelled fallback or import real local media.'}</small></div>`;
  }
  let details=panel.querySelector('.provenance-panel');
  if(p.latestOutput&&!details){
    details=document.createElement('div'); details.className='provenance-panel'; panel.appendChild(details);
  }
  if(details){
    const status=provenance.generationStatus|| (p.latestOutput.status==='blocked'?'blocked':p.latestOutput.status==='review_required'?'review required':'unknown');
    const provider=provenance.providerId||'—', model=provenance.modelId||'—', source=provenance.sourceMethod||status;
    const currentReceipt=store.state.jobs.find(j=>j.id===p.latestOutput.jobId)?.output;
    const reusedJobs=provenance.reusedFromJobs||[...new Set((currentReceipt?.interpolation?.segments||[]).map(s=>s.reusedFromJobId).filter(Boolean))];
    const resolution=provenance.resolution?.width&&provenance.resolution?.height?`${provenance.resolution.width} × ${provenance.resolution.height}`:'—';
    const finalResolution=p.latestOutput?.verification?.probe?.streams?.find(s=>s.codec_type==='video');
    const finalCanvas=provenance.deliveryResolution?`${provenance.deliveryResolution.width} × ${provenance.deliveryResolution.height}`:finalResolution?.width&&finalResolution?.height?`${finalResolution.width} × ${finalResolution.height}`:'—';
    const openSources=new Set([...details.querySelectorAll(".source-evidence[open]")].map(el=>el.dataset.sourceIndex));
    details.innerHTML=`<div class="eyebrow">OUTPUT PROVENANCE</div><div class="provenance-grid"><span>Provider</span><strong>${esc(provider)}</strong><span>Model</span><strong>${esc(model)}</strong><span>Generation</span><strong>${esc(status)}</strong><span>Source</span><strong>${esc(source)}</strong><span>Source resolution</span><strong>${esc(resolution)}</strong><span>Delivery resolution</span><strong>${esc(finalCanvas)}</strong><span>GPU memory peak (whole device)</span><strong>${esc(provenance.vramPeakGb==null?'Unmeasured':`${Number(provenance.vramPeakGb).toFixed(2)} GB`)}</strong><span>Render time</span><strong>${esc(provenance.renderTimeMs==null?'Unmeasured':`${Math.round(provenance.renderTimeMs/1000)} s`)}</strong><span>Frame rate</span><strong>${esc(provenance.targetFps?`${provenance.sourceFps} fps source → ${provenance.targetFps} fps interpolated`:`${provenance.fps||'Unrecorded'} fps`)}</strong><span>Interpolation</span><strong>${esc(provenance.interpolationMethod||'Not applied')}</strong><span>Reused stages</span><strong>${esc(reusedJobs.length?`RIFE frames from ${reusedJobs.join(', ')}`:'See per-job evidence')}</strong><span>4K method</span><strong>${esc(provenance.fourKMethod||'Not recorded')}</strong><span>Workflow hash</span><strong class="mono">${esc(provenance.workflowHash||'Not recorded')}</strong><span>Output hash</span><strong class="mono">${esc(provenance.outputHash||'Not recorded')}</strong></div>${renderSourceLineage(provenance,openSources)}${p.latestOutput.status==='review_required'?'<p>This output still needs visual review. Technical validation does not certify cinematic quality.</p>':''}`;
  }
}
function lineageLeaves(provenance,depth=0){
 if(!provenance||depth>12)return [];
 if(provenance.generationStatus==='imported')return [{upstream:provenance,sourceHash:provenance.outputHash}];
 if(Array.isArray(provenance.sources))return provenance.sources.slice(0,128).flatMap(s=>{const child=s.upstream||s.provenance;return child?lineageLeaves(child,depth+1).map(leaf=>({...leaf,sourceHash:leaf.sourceHash||s.sourceHash})):[];});
 if(provenance.source)return lineageLeaves(provenance.source,depth+1);
 return [{upstream:provenance,sourceHash:provenance.outputHash}];
}
function renderSourceLineage(provenance,openIndices=new Set()){
  const sources=provenance.sources||provenance.source?lineageLeaves(provenance):[];
  if(!sources.length)return '';
  const labels={generated:'Locally generated',imported:'Imported',upscaled:'AI upscaled',edited:'Edited',fallback:'Fallback',blocked:'Blocked'};
  return `<div class="source-lineage"><div class="eyebrow">SOURCE SHOTS · ${sources.length}</div><p>The final file is an edit. Each source retains its own generation evidence.</p>${sources.map((item,index)=>{
    const upstream=item.upstream||{},generation=upstream,status=upstream.generationStatus||upstream.status||'imported',resolution=generation.resolution;
    const values=[['Source method',labels[status]||status],['Provider',generation.providerId||'Imported local media'],['Model',generation.modelId||'No generation model claimed'],['Source resolution',resolution?`${resolution.width} × ${resolution.height}`:'Not recorded'],['Seed',generation.seed??'Not applicable'],['Visual review',generation.semanticQuality||'Not recorded'],['Generation time',generation.renderTimeMs==null?'Not measured':`${Math.round(generation.renderTimeMs/1000)} seconds`],['GPU peak (whole device)',generation.vramPeakGb==null?'Not measured':`${Number(generation.vramPeakGb).toFixed(2)} GiB`],['Source hash',item.sourceHash||generation.outputHash||'Not recorded'],['Workflow hash',generation.workflowHash||'Not applicable'],['Evidence hash',generation.evidenceHash||'Not recorded']];
    return `<details class="source-evidence" data-source-index="${index}" ${openIndices.has(String(index))?'open':''}><summary>Shot ${index+1} · ${esc(labels[status]||status)}${resolution?` · ${resolution.width} × ${resolution.height}`:''}</summary><div class="provenance-grid">${values.map(([key,value])=>`<span>${esc(key)}</span><strong ${key.includes('hash')?'class="mono"':''}>${esc(value)}</strong>`).join('')}</div>${generation.prompt?`<p class="source-prompt">${esc(generation.prompt)}</p>`:''}</details>`;
  }).join('')}</div>`;
}
